   if(service.model.running||service.pendingStart)text=t("請先熄匙，再按試音。","Stop the engine before testing.");else if(!service.audio.lastWasTest)text=t("選擇車內或車外試音。","Choose cabin or exterior test.");else if(!service.audio.error.isEmpty())text=target+t("試音失敗："," test failed: ")+service.audio.error;else if(busy)text=target+(service.audio.ready?t("試音中 "," testing ")+String.format(Locale.US,"%.1f / 2.2 s",Math.min(2.2,service.audio.frames/(double)Math.max(1,service.audio.rate))):t("試音準備中…"," test preparing…"));else if(service.audio.testCancelled)text=target+t("試音已停止。"," test stopped.");else text=target+t("試音已結束；請確認是否聽到兩聲。"," test finished; confirm you heard both tones.");if(!text.contentEquals(testStatus.getText()))testStatus.setText(text);testStatus.setTextColor(!service.audio.error.isEmpty()?RED:busy?accent(cfg):MUTED);
