 private String raw(double v,long at,long now){return Double.isFinite(v)?String.format(Locale.US,"%.3f · %d ms%s",v,Math.max(0,now-at),VehicleSnapshot.fresh(at,now)?"":t(" · 過期"," · stale")):t("未有讀值","unavailable");}
